onComplete.script:
var raw = mc.getPayloadJSON();
var parts = [];
// Normalise the aggregated shape (array, single object, or an object wrapping an array).
if (raw instanceof Array) {
  parts = raw;
} else if (raw && raw.section) {
  parts = [raw];
} else if (raw) {
  for (var k in raw) { if (raw[k] instanceof Array) { parts = raw[k]; break; } }
}
var sections = {};
for (var i = 0; i < parts.length; i++) {
  if (parts[i] && parts[i].section) { sections[String(parts[i].section)] = parts[i]; }
}
var timedOut = function (name) { return { section: name, status: 'UNAVAILABLE', reason: 'TIMEOUT' }; };
var profile = sections.profile || timedOut('profile');
var accounts = sections.accounts || timedOut('accounts');

// Data-service JSON is converted from XML: a single row may arrive as an object rather
// than an array, and all-digit strings may arrive as numbers. Normalise both.
var accountList = [];
if (String(accounts.status) === 'OK') {
  var d = accounts.data || {};
  var wrapper = d.CustomerAccounts || d.Accounts || d;
  var rows = (wrapper && (wrapper.CustomerAccount || wrapper.Account)) || [];
  if (!(rows instanceof Array)) { rows = [rows]; }
  for (var j = 0; j < rows.length; j++) {
    var r = rows[j];
    if (!r || !r.accountNumber) { continue; }
    accountList.push({
      accountNumber: String(r.accountNumber),
      accountType: String(r.accountType),
      status: String(r.status),
      balance: { amount: Number(r.balance), currency: String(r.currency) }
    });
  }
}

var profileOk = String(profile.status) === 'OK';
var accountsOk = String(accounts.status) === 'OK';
var outcome = 'OK';
if (String(profile.status) === 'NOT_FOUND') { outcome = 'NOT_FOUND'; }
else if (!profileOk && !accountsOk) { outcome = 'UNAVAILABLE'; }

var response = {
  customerId: String(mc.getProperty('uri.var.customerId')),
  partial: !(profileOk && accountsOk),
  profile: profileOk ? { status: 'OK', data: profile.data }
                     : { status: String(profile.status), reason: String(profile.reason) },
  accounts: accountsOk ? { status: 'OK', data: accountList }
                       : { status: String(accounts.status), reason: String(accounts.reason) },
  requestId: String(mc.getProperty('jamii.requestId')),
  timestamp: String(mc.getProperty('jamii.timestamp'))
};
mc.setProperty('jamii.dash.outcome', outcome);
mc.setProperty('jamii.dash.partial', String(response.partial));
mc.setPayloadJSON(response);
